/**
 * Module principal de routage de l'API KLYXOR pour ENGIE
 * Gère toutes les routes HTTP et middlewares de sécurité
 */
import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { z } from "zod";
import aiHelpRouter from "./routes/ai-help";
import indexationRouter from "./routes/indexation.routes";
import indexationRoutesV2 from "./routes/indexationRoutes";
import { registerIndexationV3Routes } from "./routes/indexationV3Routes";
import codeSnippetsRouter from "./routes/codeSnippets";
import { IndexationScheduler } from "./modules/indexation/scheduler/IndexationScheduler";
import passport from "./auth";
import { isAuthenticated, isAdmin, isContractManager, hasRole } from "./auth";
import { hasPermission } from "./permissions";
import { 
  requireAuth, 
  requirePermission, 
  requireAdmin, 
  requireValidator, 
  requireContractManager,
  requireFinanceManager 
} from "./middlewares/authMiddleware";
import bcrypt from "bcrypt";
import {
  ObjectStorageService,
  ObjectNotFoundError,
} from "./objectStorage";
import { ObjectPermission } from "./objectAcl";

/**
 * Fonction principale d'enregistrement des routes
 * Configure l'authentification, les API endpoints et les middlewares de sécurité
 * @param app - Instance Express
 * @returns Serveur HTTP configuré
 */
export async function registerRoutes(app: Express, keycloakEnabled: boolean = false): Promise<Server> {
  // ========== CONFIGURATION DE L'AUTHENTIFICATION ==========
  if (keycloakEnabled) {
    // Utiliser Keycloak OAuth2/OIDC
    console.log('🔐 Routes Keycloak OAuth2 activées');
    const keycloakRoutes = await import('./routes/authKeycloak');
    app.use('/api/auth/keycloak', keycloakRoutes.default);

    // Rediriger les anciennes routes vers Keycloak
    app.get('/api/auth/login', (req, res) => {
      res.redirect('/api/auth/keycloak/login');
    });

    app.post('/api/auth/logout', (req, res) => {
      res.redirect(307, '/api/auth/keycloak/logout');
    });

    app.get('/api/auth/check', (req, res) => {
      res.redirect('/api/auth/keycloak/check');
    });

  } else {
    // ========== ROUTES D'AUTHENTIFICATION LOCALE (FALLBACK) ==========
    console.log('⚠️ Authentification locale activée (mode développement)');
    /**
     * Route de connexion - Authentifie les utilisateurs via Passport.js
     * Utilise la stratégie locale avec bcrypt pour la sécurité
     */
    app.post("/api/auth/login", (req, res, next) => {
    passport.authenticate("local", (err: any, user: any, info: any) => {
      if (err) {
        return res.status(500).json({ error: "Erreur serveur" });
      }
      if (!user) {
        return res.status(401).json({ error: info?.message || "Authentification échouée" });
      }
      req.logIn(user, (err) => {
        if (err) {
          return res.status(500).json({ error: "Erreur de connexion" });
        }
        return res.json({ message: "Connexion réussie", user });
      });
    })(req, res, next);
    });

    /**
     * Route de déconnexion - Termine la session utilisateur
     */
    app.post("/api/auth/logout", (req, res) => {
      req.logout((err) => {
        if (err) {
          return res.status(500).json({ error: "Erreur de déconnexion" });
        }
        res.json({ message: "Déconnexion réussie" });
      });
    });

    /**
     * Vérification du statut d'authentification
     * Retourne l'état de connexion sans exposer le mot de passe
     */
    app.get("/api/auth/check", (req, res) => {
      if (req.isAuthenticated()) {
        res.json({ authenticated: true, user: req.user });
      } else {
        res.json({ authenticated: false });
      }
    });
  } // Fin des routes d'authentification locale

  // ========== ROUTES API PROTÉGÉES ==========
  /**
  app.get("/api/auth/check", (req, res) => {
    if (req.isAuthenticated()) {
      const { password: _, ...userWithoutPassword } = req.user as any;
      res.json({ authenticated: true, user: userWithoutPassword });
    } else {
      res.json({ authenticated: false });
    }
  });

  // ========== MODULE D'INDEXATION ==========
  // Gère les formules d'indexation pour les contrats énergétiques
  app.use("/api/indexation", isAuthenticated, indexationRouter);

  // Routes du nouveau moteur d'indexation V2 conforme au document ENGIE
  app.use("/api/indexation-v2", isAuthenticated, indexationRoutesV2);

  // Routes du moteur d'indexation V3 100% conforme ENGIE (seuil/cap correcté)
  registerIndexationV3Routes(app);

  // ========== MODULE DE PARTAGE DE CODE ==========
  // Gère les snippets de code avec preview et syntax highlighting
  app.use("/api/code-snippets", isAuthenticated, codeSnippetsRouter);

  // ========== INDICATEURS DE PERFORMANCE (KPIs) ==========
  /**
   * Récupère les KPIs du tableau de bord
   * Inclut validations, alertes, échéances, erreurs d'intégration
   */
  app.get("/api/kpis", isAuthenticated, async (req, res) => {
    try {
      const kpis = await storage.getKPIs();
      res.json(kpis);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch KPIs" });
    }
  });

  // ========== GESTION DES CONTRATS ==========
  /**
   * Liste tous les contrats énergétiques ENGIE
   * Inclut électricité, gaz, PPA renouvelables, maintenance
   */
  app.get("/api/contracts", isAuthenticated, async (req, res) => {
    try {
      const contracts = await storage.getContracts();
      res.json(contracts);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch contracts" });
    }
  });

  // Get contract by ID
  app.get("/api/contracts/:id", isAuthenticated, async (req, res) => {
    try {
      const contract = await storage.getContract(req.params.id);
      if (!contract) {
        return res.status(404).json({ error: "Contract not found" });
      }
      res.json(contract);
    } catch (error) {
      res.status(500).json({ error: "Failed to fetch contract" });
    }
  });

  // Create contract
  app.post("/api/contracts", requirePermission('contracts', 'create'), async (req, res) => {
    try {
      const { ContractNumberGenerator } = await import("./services/contractNumberGenerator");
      const { validateContract } = await import("./validators/contractValidator");

      // Validation backend complète des données
      const validation = validateContract(req.body);
      if (!validation.success) {
        return res.status(400).json({
          error: "Données invalides",
          message: validation.message,
          errors: validation.errors
        });
      }

      const contractData = {
        ...validation.data,
        startDate: validation.data.startDate ? new Date(validation.data.startDate) : undefined,
        endDate: validation.data.endDate ? new Date(validation.data.endDate) : undefined,
        nextIndexationDate: req.body.nextIndexationDate ? new Date(req.body.nextIndexationDate) : undefined,
        createdBy: (req as any).user?.id || 'system',
        status: 'draft'
      };

      // Generate contract number automatically if not provided
      if (!contractData.number) {
        contractData.number = await ContractNumberGenerator.generateContractNumber(
          contractData.type || 'electricity',
          contractData.businessUnit || 'ENGIE Solutions France'
        );
      }

      const contract = await storage.createContract(contractData);
      res.json(contract);
    } catch (error) {
      console.error("Error creating contract:", error);
      res.status(500).json({ error: "Failed to create contract" });
    }
  });

  // Update contract
  app.put("/api/contracts/:id", isAuthenticated, requirePermission('contracts', 'update'), async (req, res) => {
    try {
      const contractData = {
        ...req.body,
        startDate: req.body.startDate ? new Date(req.body.startDate) : undefined,
        endDate: req.body.endDate ? new Date(req.body.endDate) : undefined,
        nextIndexationDate: req.body.nextIndexationDate ? new Date(req.body.nextIndexationDate) : undefined,
      };
      const contract = await storage.updateContract(req.params.id, contractData);
      if (!contract) {
        return res.status(404).json({ error: "Contract not found" });
      }
      res.json(contract);
    } catch (error) {
      res.status(500).json({ error: "Failed to update contract" });
    }
  });

  // Update contract (PATCH method)
  app.patch("/api/contracts/:id", isAuthenticated, requirePermission('contracts', 'update'), async (req, res) => {
    try {
      // Préparer les données pour la mise à jour
      const updateData: any = {};

      // Liste des champs qui ne sont pas des dates
      const nonDateFields = [
        'indexationFrequency', 'indexationFormula', 'indexationCap',
        'indexationThreshold', 'calculationMode', 'indexationFormulaId'
      ];

      // Copier les champs non-date qui sont présents
      for (const field of nonDateFields) {
        if (req.body[field] !== undefined) {
          updateData[field] = req.body[field];
        }
      }

      // Gérer les dates spécifiquement (si présentes et non null)
      if (req.body.nextIndexationDate !== undefined) {
        updateData.nextIndexationDate = req.body.nextIndexationDate ? new Date(req.body.nextIndexationDate) : null;
      }
      if (req.body.indexTakingDate !== undefined) {
        updateData.indexTakingDate = req.body.indexTakingDate ? new Date(req.body.indexTakingDate) : null;
      }
      if (req.body.lastIndexationDate !== undefined) {
        updateData.lastIndexationDate = req.body.lastIndexationDate ? new Date(req.body.lastIndexationDate) : null;
      }
      if (req.body.startDate !== undefined) {
        updateData.startDate = req.body.startDate ? new Date(req.body.startDate) : null;
      }
      if (req.body.endDate !== undefined) {
        updateData.endDate = req.body.endDate ? new Date(req.body.endDate) : null;
      }

      const contract = await storage.updateContract(req.params.id, updateData);
      if (!contract) {
        return res.status(404).json({ error: "Contract not found" });
      }
      res.json(contract);
    } catch (error) {
      console.error("Error updating contract:", error);
      res.status(500).json({ error: "Failed to update contract" });
    }
  });

  // Delete contract
