  // Manual amount modification with justification
  app.post("/api/contracts/manual-modification", async (req, res) => {
    try {
      const {
        contractId,
        modificationType,
        currentAmount,
        newAmount,
        justification,
        effectiveDate,
        documentReference,
        approverEmail
      } = req.body;

      // Validation
      if (!contractId || !justification || justification.length < 20) {
        return res.status(400).json({ 
          error: "Contract ID et justification détaillée (min 20 caractères) requis" 
        });
      }

      // Créer l'entrée d'audit
      await storage.createAuditLog({
        userId: (req as any).user?.id || 'system',
        action: 'manual_amount_modification',
        entityType: 'contract',
        entityId: contractId,
        details: {
          modificationType,
          previousAmount: currentAmount,
          newAmount,
          justification,
          effectiveDate,
          documentReference,
          approverEmail,
          percentageChange: ((newAmount - currentAmount) / currentAmount * 100).toFixed(2)
        },
        ipAddress: req.ip || '',
        userAgent: req.headers['user-agent'] || ''
      });

      // Mettre à jour le contrat
      const updatedContract = await storage.updateContract(contractId, {
        amount: newAmount,
        lastManualModification: new Date(),
        lastModificationJustification: justification,
        updatedAt: new Date()
      });

      res.json({
        success: true,
        contract: updatedContract,
        message: "Modification manuelle enregistrée avec succès"
      });
    } catch (error) {
      console.error('Error in manual modification:', error);
      res.status(500).json({ error: "Failed to process manual modification" });
    }
  });

