import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from "@/components/ui/dialog";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { useToast } from "@/hooks/use-toast";
import { usePermissions } from "@/hooks/usePermissions";
import { 
  FileText, FileUp, Plus, Download, RefreshCw, Eye, Edit2, 
  AlertTriangle, CheckCircle, Clock, XCircle, Calendar,
  DollarSign, Building2, Globe, Hash, Info, Upload, X,
  ChevronRight, ChevronLeft, Save, Send, FileCheck
} from "lucide-react";
import { apiRequest } from "@/lib/queryClient";
import type { Contract } from "@shared/schema";
import { AIHelpBubble } from "@/components/widgets/ai-help-bubble";
import { useAIHelp } from "@/components/widgets/ai-help-context";
import { ConfirmModal } from "@/components/common/confirm-modal";

export default function Contracts() {
  const { canCreateContract, canExportData } = usePermissions();
  const { setPage } = useAIHelp();
  const [activeTab, setActiveTab] = useState("list");
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [typeFilter, setTypeFilter] = useState<string>("all");
  const [businessUnitFilter, setBusinessUnitFilter] = useState<string>("all");
  const [periodFilter, setPeriodFilter] = useState<string>("all");
  const [itemsPerPage, setItemsPerPage] = useState("25");

  // Wizard states
  const [wizardStep, setWizardStep] = useState(1);
  const [showWizard, setShowWizard] = useState(false);
  const [wizardData, setWizardData] = useState<any>({});

  // Contract details
  const [showContractDetails, setShowContractDetails] = useState(false);
  const [selectedContract, setSelectedContract] = useState<any>(null);

  // Validation modal
  const [showValidationModal, setShowValidationModal] = useState(false);
  const [validationDecision, setValidationDecision] = useState<"validate" | "reject" | "">("");
  const [rejectionReason, setRejectionReason] = useState("");
  const [validationComment, setValidationComment] = useState("");

  // Amendment modal
  const [showAmendmentModal, setShowAmendmentModal] = useState(false);
  const [amendmentData, setAmendmentData] = useState<any>({
    contractId: "",
    type: "price_revision",
    title: "",
    description: "",
    effectiveDate: new Date().toISOString().split('T')[0],
    newAmount: "",
    impactDescription: ""
  });

  // Termination modal
  const [showTerminationModal, setShowTerminationModal] = useState(false);
  const [terminationData, setTerminationData] = useState<any>({
    contractId: "",
