                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>

            {/* Modal Avenant */}
            <Dialog open={showAmendmentModal} onOpenChange={setShowAmendmentModal}>
              <DialogContent className="w-[95vw] max-w-[600px] max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                  <DialogTitle>Créer un avenant</DialogTitle>
                  <DialogDescription>
                    Remplissez les informations pour créer un avenant au contrat
                  </DialogDescription>
                </DialogHeader>

                <div className="space-y-4">
                  <div>
                    <Label>Sélectionner le contrat *</Label>
                    <Select 
                      value={amendmentData.contractId}
                      onValueChange={(value) => setAmendmentData({...amendmentData, contractId: value})}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Choisir un contrat" />
                      </SelectTrigger>
                      <SelectContent>
                        {contracts.filter(c => c.status === "active").map((contract) => (
                          <SelectItem key={contract.id} value={contract.id}>
                            {contract.number} - {contract.title}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  {amendmentData.contractId && (() => {
                    const selectedContractForAmendment = contracts.find(c => c.id === amendmentData.contractId);
                    return selectedContractForAmendment ? (
                      <div className="bg-gray-50 p-3 rounded text-sm">
                        <div>Contrat : {selectedContractForAmendment.number}</div>
                        <div>Titre : {selectedContractForAmendment.title}</div>
                        <div>Montant actuel : {formatAmount(selectedContractForAmendment.amount, selectedContractForAmendment.currency)}</div>
                      </div>
                    ) : null;
                  })()}

                    <div>
                      <Label>Type d'avenant *</Label>
                      <Select 
                        value={amendmentData.type}
                        onValueChange={(value) => setAmendmentData({...amendmentData, type: value})}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="price_revision">Révision de prix</SelectItem>
                          <SelectItem value="scope_change">Modification du périmètre</SelectItem>
                          <SelectItem value="duration_extension">Extension de durée</SelectItem>
                          <SelectItem value="indexation_change">Modification d'indexation</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <div>
                      <Label>Titre de l'avenant *</Label>
                      <Input
                        value={amendmentData.title}
                        onChange={(e) => setAmendmentData({...amendmentData, title: e.target.value})}
                        placeholder="Ex: Avenant n°1 - Révision tarifaire"
                      />
                    </div>

                    <div>
                      <Label>Description</Label>
                      <Textarea
                        value={amendmentData.description}
                        onChange={(e) => setAmendmentData({...amendmentData, description: e.target.value})}
                        placeholder="Description détaillée de l'avenant..."
                        rows={3}
                      />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <Label>Date d'effet *</Label>
                        <Input
                          type="date"
                          value={amendmentData.effectiveDate}
                          onChange={(e) => setAmendmentData({...amendmentData, effectiveDate: e.target.value})}
                        />
                      </div>
                      {amendmentData.type === "price_revision" && (
                        <div>
                          <Label>Nouveau montant *</Label>
                          <Input
                            type="number"
                            value={amendmentData.newAmount}
                            onChange={(e) => setAmendmentData({...amendmentData, newAmount: e.target.value})}
                            placeholder="0.00"
                          />
                        </div>
                      )}
                    </div>

                    <div>
                      <Label>Impact sur le contrat</Label>
                      <Textarea
                        value={amendmentData.impactDescription}
                        onChange={(e) => setAmendmentData({...amendmentData, impactDescription: e.target.value})}
                        placeholder="Décrire l'impact de cet avenant sur le contrat..."
                        rows={2}
                      />
                    </div>
                </div>

                <DialogFooter>
                  <Button variant="outline" onClick={() => setShowAmendmentModal(false)}>
                    Annuler
                  </Button>
                  <Button 
                    onClick={() => {
                      const selectedContractForAmendment = contracts.find(c => c.id === amendmentData.contractId);
                      if (selectedContractForAmendment) {
                        const amendmentNumber = `AVN-${selectedContractForAmendment.number}-${String(Date.now()).slice(-3)}`;
                        createAmendmentMutation.mutate({
                          contractId: amendmentData.contractId,
                          number: amendmentNumber,
                          type: amendmentData.type,
                          title: amendmentData.title,
                          description: amendmentData.description,
                          status: "draft",
                          effectiveDate: amendmentData.effectiveDate,
                          originalAmount: selectedContractForAmendment.amount,
                          newAmount: amendmentData.newAmount || selectedContractForAmendment.amount,
                          impactDescription: amendmentData.impactDescription,
                          requestedBy: "admin-1"
                        });
                      }
                    }}
                    disabled={!amendmentData.contractId || !amendmentData.title || !amendmentData.effectiveDate || createAmendmentMutation.isPending}
                  >
                    {createAmendmentMutation.isPending ? "Création..." : "Créer l'avenant"}
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>

            {/* Modal Résiliation */}
            <Dialog open={showTerminationModal} onOpenChange={setShowTerminationModal}>
              <DialogContent className="w-[95vw] max-w-[500px]">
                <DialogHeader>
                  <DialogTitle>Demande de résiliation</DialogTitle>
                  <DialogDescription>
                    Créer une demande de résiliation pour ce contrat
                  </DialogDescription>
                </DialogHeader>

                <div className="space-y-4">
                  <Alert className="border-red-200 bg-red-50">
                    <AlertTriangle className="h-4 w-4 text-red-600" />
                    <AlertDescription className="text-red-800">
                      Cette action créera une demande de résiliation qui devra être validée.
                    </AlertDescription>
                  </Alert>

                  <div>
                    <Label>Sélectionner le contrat à résilier *</Label>
                    <Select 
                      value={terminationData.contractId}
                      onValueChange={(value) => setTerminationData({...terminationData, contractId: value})}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Choisir un contrat" />
                      </SelectTrigger>
                      <SelectContent>
                        {contracts.filter(c => c.status === "active").map((contract) => (
                          <SelectItem key={contract.id} value={contract.id}>
                            {contract.number} - {contract.title}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  {terminationData.contractId && (() => {
                    const selectedContractForTermination = contracts.find(c => c.id === terminationData.contractId);
                    return selectedContractForTermination ? (
                      <div className="bg-gray-50 p-3 rounded text-sm">
                        <div>Contrat : {selectedContractForTermination.number}</div>
                        <div>Titre : {selectedContractForTermination.title}</div>
                        <div>Type : {selectedContractForTermination.type}</div>
                      </div>
                    ) : null;
                  })()}

                  <div>
                    <Label>Date de résiliation souhaitée *</Label>
                    <Input
                      type="date"
                      value={terminationData.terminationDate}
                      onChange={(e) => setTerminationData({...terminationData, terminationDate: e.target.value})}
                      min={new Date().toISOString().split('T')[0]}
                    />
                  </div>

                  <div>
                    <Label>Motif de résiliation *</Label>
                    <Textarea
                      value={terminationData.terminationReason}
                      onChange={(e) => setTerminationData({...terminationData, terminationReason: e.target.value})}
                      placeholder="Indiquer le motif de la résiliation..."
                      rows={3}
                    />
                  </div>
                </div>

                <DialogFooter>
                  <Button variant="outline" onClick={() => setShowTerminationModal(false)}>
                    Annuler
                  </Button>
                  <Button 
                    variant="destructive"
                    onClick={() => {
                      const selectedContractForTermination = contracts.find(c => c.id === terminationData.contractId);
                      if (selectedContractForTermination) {
                        createTerminationMutation.mutate({
                          type: "termination",
                          referenceId: terminationData.contractId,
                          reference: selectedContractForTermination.number,
                          subject: `Résiliation du contrat ${selectedContractForTermination.number}`,
                          requestedBy: "admin-1",
                          assignedTo: "validator-1",
                          reason: terminationData.terminationReason,
                          status: "pending"
                        });
                      }
                    }}
                    disabled={!terminationData.contractId || !terminationData.terminationReason || !terminationData.terminationDate || createTerminationMutation.isPending}
                  >
                    {createTerminationMutation.isPending ? "Création..." : "Créer la demande"}
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>

            {/* Modal de confirmation de suppression */}
            <ConfirmModal
              open={showDeleteModal}
              onOpenChange={setShowDeleteModal}
              title="Supprimer le contrat"
              description={`Êtes-vous sûr de vouloir supprimer le contrat "${contractToDelete?.number}" ? Cette action changera le statut du contrat en "supprimé".`}
              confirmText="Supprimer"
              cancelText="Annuler"
              variant="destructive"
              onConfirm={() => {
                console.log('Suppression du contrat:', contractToDelete);
                setShowDeleteModal(false);
                setContractToDelete(null);
              }}
            />

            {/* Modal de confirmation de changement de statut */}
            <ConfirmModal
              open={showStatusChangeModal}
              onOpenChange={setShowStatusChangeModal}
              title="Changer le statut du contrat"
              description={`Êtes-vous sûr de vouloir changer le statut du contrat de "${statusChangeData.oldStatus}" à "${statusChangeData.newStatus}" ?`}
              confirmText="Confirmer"
              cancelText="Annuler"
              variant="default"
              onConfirm={() => {
                console.log('Changement de statut:', statusChangeData);
                setShowStatusChangeModal(false);
                setStatusChangeData({ contractId: "", newStatus: "", oldStatus: "" });
              }}
            />

            {/* Modal d'export avancé */}
            <Dialog open={showExportModal} onOpenChange={setShowExportModal}>
              <DialogContent data-testid="export-modal">
                <DialogHeader>
                  <DialogTitle>Exporter les contrats</DialogTitle>
                  <DialogDescription>
                    Configurez les options d'export pour générer votre fichier
                  </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-4">
                  <div>
                    <Label htmlFor="export-format">Format d'export</Label>
                    <Select defaultValue="excel">
                      <SelectTrigger id="export-format">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="excel">Excel (.xlsx)</SelectItem>
                        <SelectItem value="csv">CSV (.csv)</SelectItem>
                        <SelectItem value="pdf">PDF (.pdf)</SelectItem>
                        <SelectItem value="json">JSON (.json)</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <Label htmlFor="export-range">Période</Label>
                    <Select defaultValue="current">
                      <SelectTrigger id="export-range">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="current">Filtres actuels</SelectItem>
                        <SelectItem value="all">Tous les contrats</SelectItem>
                        <SelectItem value="active">Contrats actifs uniquement</SelectItem>
                        <SelectItem value="custom">Période personnalisée</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <Label>Colonnes à inclure</Label>
                    <div className="space-y-2 mt-2">
                      <div className="flex items-center space-x-2">
                        <input type="checkbox" id="col-basic" defaultChecked />
                        <Label htmlFor="col-basic" className="cursor-pointer">Informations de base</Label>
                      </div>
                      <div className="flex items-center space-x-2">
                        <input type="checkbox" id="col-financial" defaultChecked />
                        <Label htmlFor="col-financial" className="cursor-pointer">Données financières</Label>
                      </div>
                      <div className="flex items-center space-x-2">
                        <input type="checkbox" id="col-dates" defaultChecked />
                        <Label htmlFor="col-dates" className="cursor-pointer">Dates importantes</Label>
                      </div>
                      <div className="flex items-center space-x-2">
                        <input type="checkbox" id="col-kpi" />
                        <Label htmlFor="col-kpi" className="cursor-pointer">Indicateurs KPI</Label>
                      </div>
                    </div>
                  </div>
                </div>
                <DialogFooter>
                  <Button variant="outline" onClick={() => setShowExportModal(false)}>
                    Annuler
                  </Button>
                  <Button onClick={() => {
                    console.log('Export des contrats');
                    setShowExportModal(false);
                  }}>
                    <Download className="w-4 h-4 mr-2" />
                    Télécharger
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>
          </div>
        </main>
    </div>
  );
}

