                      <SelectTrigger id="contract-select">
                        <SelectValue placeholder="Sélectionner un contrat" />
                      </SelectTrigger>
                      <SelectContent>
                        {contracts.map((contract: any) => (
                          <SelectItem key={contract.id} value={contract.id}>
                            {contract.number} - {contract.title}
