                </div>
                <DialogFooter>
                  <Button variant="outline" onClick={() => setShowEditModal(false)}>
                    Annuler
                  </Button>
                  <Button onClick={() => {
                    console.log('Modification métadonnées:', editForm);
                    setShowEditModal(false);
