                          </div>
                          <div className="mt-3">
                            <p className="text-sm text-gray-600">Justification fournie:</p>
                            <p className="text-sm mt-1">Extension du périmètre suite à l'ajout de nouveaux services.</p>
                          </div>
                        </div>
                      </div>

                      {/* Pièces jointes */}
                      <div className="space-y-3">
                        <h3 className="font-medium text-gray-900">Pièces jointes</h3>
                        <div className="space-y-2">
                          <div className="flex items-center justify-between p-2 bg-gray-50 rounded">
                            <div className="flex items-center space-x-2">
                              <Paperclip className="w-4 h-4 text-gray-500" />
                              <span className="text-sm">Avenant_contrat.pdf</span>
                            </div>
                            <span className="text-xs text-gray-500">15/01/2024</span>
                          </div>
                          <div className="flex items-center justify-between p-2 bg-gray-50 rounded">
                            <div className="flex items-center space-x-2">
                              <Paperclip className="w-4 h-4 text-gray-500" />
                              <span className="text-sm">Justificatifs.xlsx</span>
                            </div>
                            <span className="text-xs text-gray-500">15/01/2024</span>
                          </div>
                        </div>
                      </div>

                      {/* Traçabilité de la demande */}
                      <div className="space-y-3">
                        <h3 className="font-medium text-gray-900">Traçabilité de la demande</h3>
                        <div className="space-y-2 text-sm">
                          <div className="flex justify-between">
                            <span className="text-gray-600">Créée:</span>
                            <span>{formatDate(selectedRequest.createdAt)}</span>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-gray-600">Affectée:</span>
                            <span>{formatDate(selectedRequest.createdAt || new Date())}</span>
                          </div>
                          {selectedRequest.age > 1 && (
                            <div className="flex justify-between">
                              <span className="text-gray-600">Relance &gt; 24h:</span>
                              <span className="text-orange-600">{formatDate(new Date(Date.now() - 24 * 60 * 60 * 1000))}</span>
                            </div>
                          )}
                          <div className="flex justify-between">
                            <span className="text-gray-600">Trace-ID:</span>
                            <span className="font-mono text-xs">TRC-2024-{Math.floor(Math.random() * 10000)}</span>
                          </div>
                        </div>
                      </div>

                      {/* Règles & contrôles */}
                      {selectedRequest.type === "contract" && (
                        <Alert>
                          <Info className="h-4 w-4" />
                          <AlertDescription>
                            <strong>Contrats:</strong> Rappel de la séparation des rôles (créateur ≠ valideur).
                            <br />
                            <strong>Toutes demandes:</strong> Motif obligatoire en cas de rejet.
                          </AlertDescription>
                        </Alert>
                      )}

                      {/* Zone de décision */}
                      {selectedRequest.status === "pending" && (
                        <div className="space-y-4 border-t pt-4">
                          <h3 className="font-medium text-gray-900">Décision</h3>

                          <RadioGroup value={decision} onValueChange={(value: any) => setDecision(value)}>
                            <div className="flex items-center space-x-2">
                              <RadioGroupItem value="approve" id="approve" />
                              <Label htmlFor="approve" className="text-green-600">Approuver</Label>
                            </div>
                            <div className="flex items-center space-x-2">
                              <RadioGroupItem value="reject" id="reject" />
                              <Label htmlFor="reject" className="text-red-600">Rejeter</Label>
                            </div>
                          </RadioGroup>

                          {decision === "reject" && (
                            <div>
                              <Label>Motif (obligatoire)</Label>
                              <Textarea
                                value={rejectReason}
                                onChange={(e) => setRejectReason(e.target.value)}
                                placeholder="Indiquer le motif du rejet..."
                                className="mt-1"
                              />
                            </div>
                          )}

                          <div>
                            <Label>Transférer à (optionnel)</Label>
                            <Select value={transferTo} onValueChange={setTransferTo}>
                              <SelectTrigger className="mt-1">
                                <SelectValue placeholder="Sélectionner une personne" />
                              </SelectTrigger>
                              <SelectContent>
                                {validators.length === 0 ? (
                                  <SelectItem value="none" disabled>
                                    Aucun validateur disponible
                                  </SelectItem>
                                ) : (
                                  validators.map((user: any) => (
                                    <SelectItem key={user.id} value={user.id}>
                                      {user.firstName} {user.lastName} - {user.role === 'admin' ? 'Administrateur' : user.role === 'manager' ? 'Gestionnaire' : 'Validateur'}
                                    </SelectItem>
                                  ))
                                )}
                              </SelectContent>
                            </Select>
                          </div>

                          <div>
                            <Label>Commentaire interne (optionnel)</Label>
                            <Textarea
                              value={internalComment}
                              onChange={(e) => setInternalComment(e.target.value)}
                              placeholder="Commentaire interne..."
                              className="mt-1"
                            />
                          </div>

                          <div className="flex space-x-2">
                            <Button
                              onClick={handleDecision}
                              disabled={
                                (!decision && !transferTo) || 
                                (decision === "reject" && !rejectReason)
                              }
                              variant={decision === "approve" ? "default" : decision === "reject" ? "destructive" : "outline"}
                            >
                              {decision === "approve" ? "Approuver" : 
                               decision === "reject" ? "Rejeter" :
                               transferTo ? "Transférer" : "Valider"}
                            </Button>
                            <Button 
                              variant="outline"
                              onClick={() => setShowDetailsPanel(false)}
                            >
                              Fermer
                            </Button>
                          </div>
                        </div>
                      )}

                      {/* Liens rapides */}
                      <div className="space-y-2 pt-4 border-t">
                        <Button variant="outline" className="w-full">
                          <ArrowRight className="w-4 h-4 mr-2" />
                          Ouvrir la fiche contrat
                        </Button>
                      </div>
                    </div>
                  </>
                )}
              </SheetContent>
            </Sheet>

            {/* Modal de confirmation d'approbation */}
            <ConfirmModal
              open={showApproveModal}
              onOpenChange={setShowApproveModal}
              title="Approuver la demande"
              description={`Êtes-vous sûr de vouloir approuver la demande de validation #${selectedRequest?.reference} ?`}
              confirmText="Approuver"
              cancelText="Annuler"
              variant="default"
              onConfirm={() => {
                if (selectedRequest) {
                  approveMutation.mutate(selectedRequest.id);
                  setShowApproveModal(false);
                  setShowDetailsPanel(false);
                }
              }}
            />

            {/* Modal de confirmation de rejet */}
            <Dialog open={showRejectModal} onOpenChange={setShowRejectModal}>
              <DialogContent data-testid="reject-modal">
                <DialogHeader>
                  <DialogTitle>Rejeter la demande</DialogTitle>
                  <DialogDescription>
                    Veuillez indiquer le motif du rejet pour la demande #{selectedRequest?.reference}
                  </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-4">
                  <div>
                    <Label htmlFor="reject-reason">Motif du rejet *</Label>
                    <Textarea
                      id="reject-reason"
                      value={rejectReason}
                      onChange={(e) => setRejectReason(e.target.value)}
                      placeholder="Expliquez la raison du rejet..."
                      rows={4}
                    />
                  </div>
                  <div>
                    <Label htmlFor="reject-comment">Commentaire interne (optionnel)</Label>
                    <Textarea
                      id="reject-comment"
                      value={internalComment}
                      onChange={(e) => setInternalComment(e.target.value)}
                      placeholder="Commentaire visible uniquement en interne..."
                      rows={2}
                    />
                  </div>
                </div>
                <DialogFooter>
                  <Button variant="outline" onClick={() => setShowRejectModal(false)}>
                    Annuler
                  </Button>
                  <Button 
                    variant="destructive"
                    disabled={!rejectReason}
                    onClick={() => {
                      if (selectedRequest && rejectReason) {
                        rejectMutation.mutate({ id: selectedRequest.id, reason: rejectReason });
                        setShowRejectModal(false);
                        setRejectReason("");
                        setInternalComment("");
                      }
                    }}
                  >
                    Rejeter la demande
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>

            {/* Modal de transfert */}
            <Dialog open={showTransferModal} onOpenChange={setShowTransferModal}>
              <DialogContent data-testid="transfer-modal">
                <DialogHeader>
                  <DialogTitle>Transférer la demande</DialogTitle>
                  <DialogDescription>
                    Transférer la demande de validation à un autre validateur
                  </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-4">
                  <div>
                    <Label htmlFor="transfer-to">Transférer à *</Label>
                    <Select value={transferTo} onValueChange={setTransferTo}>
                      <SelectTrigger id="transfer-to">
                        <SelectValue placeholder="Sélectionnez un validateur" />
                      </SelectTrigger>
                      <SelectContent>
                        {validators.length === 0 ? (
                          <SelectItem value="none" disabled>
                            Aucun validateur disponible
                          </SelectItem>
                        ) : (
                          validators.map((user: any) => (
                            <SelectItem key={user.id} value={user.id}>
                              {user.firstName} {user.lastName} ({user.email}) - {user.role === 'admin' ? 'Administrateur' : user.role === 'manager' ? 'Gestionnaire' : 'Validateur'}
                            </SelectItem>
                          ))
                        )}
                      </SelectContent>
                    </Select>
                  </div>
                  <div>
                    <Label htmlFor="transfer-note">Note de transfert</Label>
                    <Textarea
                      id="transfer-note"
                      placeholder="Ajoutez une note pour le nouveau validateur..."
                      rows={3}
                    />
                  </div>
                </div>
                <DialogFooter>
                  <Button variant="outline" onClick={() => setShowTransferModal(false)}>
                    Annuler
                  </Button>
                  <Button 
                    disabled={!transferTo}
                    onClick={() => {
                      console.log('Transfert à:', transferTo);
                      setShowTransferModal(false);
                      setTransferTo("");
                      const selectedValidator = validators.find((v: any) => v.id === transferTo);
                      toast({
                        title: "Demande transférée",
                        description: `La demande a été transférée à ${selectedValidator ? selectedValidator.firstName + ' ' + selectedValidator.lastName : transferTo}`,
                      });
                    }}
                  >
                    Transférer
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>

            {/* Modal d'action groupée */}
            <Dialog open={showBulkActionModal} onOpenChange={setShowBulkActionModal}>
              <DialogContent data-testid="bulk-action-modal">
                <DialogHeader>
                  <DialogTitle>Action groupée</DialogTitle>
                  <DialogDescription>
                    Appliquer une action à {selectedRequests.length} demandes sélectionnées
                  </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-4">
                  <RadioGroup value={bulkAction} onValueChange={(v) => setBulkAction(v as any)}>
                    <div className="flex items-center space-x-2">
                      <RadioGroupItem value="approve" id="bulk-approve" />
                      <Label htmlFor="bulk-approve" className="cursor-pointer">
                        Approuver toutes les demandes
                      </Label>
                    </div>
                    <div className="flex items-center space-x-2">
                      <RadioGroupItem value="reject" id="bulk-reject" />
                      <Label htmlFor="bulk-reject" className="cursor-pointer">
                        Rejeter toutes les demandes
                      </Label>
                    </div>
                  </RadioGroup>

                  {bulkAction === "reject" && (
                    <div>
                      <Label htmlFor="bulk-reject-reason">Motif du rejet *</Label>
                      <Textarea
                        id="bulk-reject-reason"
                        placeholder="Motif commun pour tous les rejets..."
                        rows={3}
                      />
                    </div>
                  )}
                </div>
                <DialogFooter>
                  <Button variant="outline" onClick={() => setShowBulkActionModal(false)}>
                    Annuler
                  </Button>
                  <Button 
                    disabled={!bulkAction}
                    variant={bulkAction === "reject" ? "destructive" : "default"}
                    onClick={() => {
                      console.log('Action groupée:', bulkAction, 'sur', selectedRequests);
                      setShowBulkActionModal(false);
                      setBulkAction("");
                      setSelectedRequests([]);
                      toast({
                        title: "Action groupée effectuée",
                        description: `${selectedRequests.length} demandes ont été ${bulkAction === "approve" ? "approuvées" : "rejetées"}`,
                      });
                    }}
                  >
                    {bulkAction === "approve" ? "Approuver" : "Rejeter"} ({selectedRequests.length})
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>
          </div>
        </main>
    </div>
  );
}

client/src/components/common/rejection-m.content:
import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";

interface RejectionModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (reason: string) => void;
  title?: string;
  description?: string;
  isLoading?: boolean;
}

export default function RejectionModal({
  isOpen,
  onClose,
  onConfirm,
  title = "Motif de rejet",
  description = "Veuillez indiquer le motif du rejet. Ce champ est obligatoire.",
  isLoading = false,
}: RejectionModalProps) {
  const [reason, setReason] = useState("");
  const [error, setError] = useState("");

  const handleConfirm = () => {
    if (!reason.trim()) {
      setError("Le motif de rejet est obligatoire");
      return;
    }

    onConfirm(reason.trim());
    handleClose();
  };

  const handleClose = () => {
    setReason("");
    setError("");
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-md" data-testid="rejection-modal">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          <Textarea
            placeholder="Veuillez indiquer le motif du rejet..."
            value={reason}
            onChange={(e) => {
              setReason(e.target.value);
              if (error) setError("");
            }}
            className={`min-h-[120px] resize-none ${error ? "border-red-500" : ""}`}
            data-testid="textarea-rejection-reason"
          />
          {error && (
            <p className="text-sm text-red-600" data-testid="error-message">
              {error}
            </p>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={handleClose}
            disabled={isLoading}
            data-testid="button-cancel-rejection"
          >
            Annuler
          </Button>
          <Button
            variant="destructive"
            onClick={handleConfirm}
            disabled={isLoading}
            data-testid="button-confirm-rejection"
          >
            {isLoading ? "Traitement..." : "Confirmer le rejet"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

