  {
    id: "indexations",
    label: "Indexations (Admin)",
    icon: TrendingUp,
    path: "/admin/indexations",
    subItems: [
      { label: "À calculer", path: "/admin/indexations/calculate" },
      { label: "À valider", path: "/admin/indexations/validate" },
      { label: "Historique", path: "/admin/indexations/history" },
