/* ===== RESPONSIVE FIXES FOR KLYXOR ===== */

/* 1. Global Mobile Improvements */
@media (max-width: 640px) {
  /* Fix for modals on mobile */
  .dialog-content,
  .sheet-content {
    width: 95vw !important;
    max-width: 95vw !important;
    margin: auto;
