    font-size: 1.5rem;
  }
}

/* 7. Sidebar responsiveness */
@media (max-width: 768px) {
  .sidebar {
    position: fixed;
    left: -100%;
    transition: left 0.3s ease;
    z-index: 50;
  }

  .sidebar.open {
    left: 0;
  }

  .main-content {
    margin-left: 0 !important;
  }
}

/* 8. Better scrolling on mobile */
* {
  -webkit-tap-highlight-color: transparent;
}

/* 9. Fix for form inputs on iOS */
