  font-size: 16px !important;
}

@media (max-width: 640px) {
  input, textarea, select {
    font-size: 16px !important;
  }
}

/* 10. Responsive tables */
@media (max-width: 768px) {
  .responsive-table {
    display: block;
    overflow-x: auto;
    white-space: nowrap;
  }

  .responsive-table table {
    min-width: 600px;
  }
}

/* 11. Modal responsive improvements */
.modal-responsive {
  max-height: 90vh;
  overflow-y: auto;
}

@media (max-width: 640px) {
  .modal-responsive {
    max-height: 85vh;
