import { Storage, File } from "@google-cloud/storage";
import { Response } from "express";
import { randomUUID } from "crypto";
import {
  ObjectAclPolicy,
  ObjectPermission,
  canAccessObject,
  getObjectAclPolicy,
  setObjectAclPolicy,
} from "./objectAcl";

const REPLIT_SIDECAR_ENDPOINT = "http://127.0.0.1:1106";

// The object storage client is used to interact with the object storage service.
export const objectStorageClient = new Storage({
  credentials: {
    audience: "replit",
    subject_token_type: "access_token",
    token_url: `${REPLIT_SIDECAR_ENDPOINT}/token`,
    type: "external_account",
    credential_source: {
      url: `${REPLIT_SIDECAR_ENDPOINT}/credential`,
      format: {
        type: "json",
        subject_token_field_name: "access_token",
      },
    },
    universe_domain: "googleapis.com",
  },
  projectId: "",
});

export class ObjectNotFoundError extends Error {
  constructor() {
    super("Object not found");
    this.name = "ObjectNotFoundError";
    Object.setPrototypeOf(this, ObjectNotFoundError.prototype);
  }
}

// The object storage service is used to interact with the object storage service.
export class ObjectStorageService {
  constructor() {}

  // Gets the public object search paths.
  getPublicObjectSearchPaths(): Array<string> {
    const pathsStr = process.env.PUBLIC_OBJECT_SEARCH_PATHS || "";
    const paths = Array.from(
      new Set(
        pathsStr
          .split(",")
          .map((path) => path.trim())
          .filter((path) => path.length > 0)
      )
    );
    if (paths.length === 0) {
      throw new Error(
        "PUBLIC_OBJECT_SEARCH_PATHS not set. Create a bucket in 'Object Storage' " +
          "tool and set PUBLIC_OBJECT_SEARCH_PATHS env var (comma-separated paths)."
      );
    }
    return paths;
  }

  // Gets the private object directory.
  getPrivateObjectDir(): string {
    const dir = process.env.PRIVATE_OBJECT_DIR || "";
    if (!dir) {
      throw new Error(
        "PRIVATE_OBJECT_DIR not set. Create a bucket in 'Object Storage' " +
          "tool and set PRIVATE_OBJECT_DIR env var."
      );
    }
    return dir;
  }

  // Search for a public object from the search paths.
  async searchPublicObject(filePath: string): Promise<File | null> {
    for (const searchPath of this.getPublicObjectSearchPaths()) {
      const fullPath = `${searchPath}/${filePath}`;

      // Full path format: /<bucket_name>/<object_name>
      const { bucketName, objectName } = parseObjectPath(fullPath);
      const bucket = objectStorageClient.bucket(bucketName);
      const file = bucket.file(objectName);

      // Check if file exists
      const [exists] = await file.exists();
      if (exists) {
        return file;
      }
    }

    return null;
  }

  // Downloads an object to the response.
  async downloadObject(file: File, res: Response, cacheTtlSec: number = 3600) {
    try {
      // Get file metadata
      const [metadata] = await file.getMetadata();
      // Get the ACL policy for the object.
      const aclPolicy = await getObjectAclPolicy(file);
      const isPublic = aclPolicy?.visibility === "public";
      // Set appropriate headers
      res.set({
        "Content-Type": metadata.contentType || "application/octet-stream",
        "Content-Length": metadata.size,
        "Cache-Control": `${
          isPublic ? "public" : "private"
        }, max-age=${cacheTtlSec}`,
      });

      // Stream the file to the response
      const stream = file.createReadStream();

      stream.on("error", (err) => {
        console.error("Stream error:", err);
        if (!res.headersSent) {
          res.status(500).json({ error: "Error streaming file" });
        }
      });

      stream.pipe(res);
    } catch (error) {
      console.error("Error downloading file:", error);
      if (!res.headersSent) {
        res.status(500).json({ error: "Error downloading file" });
      }
    }
  }

  // Gets the upload URL for an object entity.
  async getObjectEntityUploadURL(): Promise<string> {
    const privateObjectDir = this.getPrivateObjectDir();
    if (!privateObjectDir) {
      throw new Error(
        "PRIVATE_OBJECT_DIR not set. Create a bucket in 'Object Storage' " +
          "tool and set PRIVATE_OBJECT_DIR env var."
      );
    }

    const objectId = randomUUID();
    const fullPath = `${privateObjectDir}/uploads/${objectId}`;

    const { bucketName, objectName } = parseObjectPath(fullPath);

    // Sign URL for PUT method with TTL
    return signObjectURL({
      bucketName,
      objectName,
      method: "PUT",
      ttlSec: 900,
    });
  }

  // Gets the object entity file from the object path.
  async getObjectEntityFile(objectPath: string): Promise<File> {
    if (!objectPath.startsWith("/objects/")) {
      throw new ObjectNotFoundError();
    }

    const parts = objectPath.slice(1).split("/");
    if (parts.length < 2) {
      throw new ObjectNotFoundError();
    }

    const entityId = parts.slice(1).join("/");
    let entityDir = this.getPrivateObjectDir();
    if (!entityDir.endsWith("/")) {
      entityDir = `${entityDir}/`;
    }
    const objectEntityPath = `${entityDir}${entityId}`;
    const { bucketName, objectName } = parseObjectPath(objectEntityPath);
    const bucket = objectStorageClient.bucket(bucketName);
    const objectFile = bucket.file(objectName);
    const [exists] = await objectFile.exists();
    if (!exists) {
      throw new ObjectNotFoundError();
    }
    return objectFile;
  }

  normalizeObjectEntityPath(
    rawPath: string,
  ): string {
    if (!rawPath.startsWith("https://storage.googleapis.com/")) {
      return rawPath;
    }

    // Extract the path from the URL by removing query parameters and domain
    const url = new URL(rawPath);
    const rawObjectPath = url.pathname;

    let objectEntityDir = this.getPrivateObjectDir();
    if (!objectEntityDir.endsWith("/")) {
      objectEntityDir = `${objectEntityDir}/`;
    }

    if (!rawObjectPath.startsWith(objectEntityDir)) {
      return rawObjectPath;
    }

    // Extract the entity ID from the path
    const entityId = rawObjectPath.slice(objectEntityDir.length);
    return `/objects/${entityId}`;
  }

  // Tries to set the ACL policy for the object entity and return the normalized path.
  async trySetObjectEntityAclPolicy(
    rawPath: string,
    aclPolicy: ObjectAclPolicy
  ): Promise<string> {
    const normalizedPath = this.normalizeObjectEntityPath(rawPath);
    if (!normalizedPath.startsWith("/")) {
      return normalizedPath;
    }

    const objectFile = await this.getObjectEntityFile(normalizedPath);
    await setObjectAclPolicy(objectFile, aclPolicy);
    return normalizedPath;
  }

  // Checks if the user can access the object entity.
  async canAccessObjectEntity({
    userId,
    objectFile,
    requestedPermission,
  }: {
    userId?: string;
    objectFile: File;
    requestedPermission?: ObjectPermission;
  }): Promise<boolean> {
    return canAccessObject({
      userId,
      objectFile,
      requestedPermission: requestedPermission ?? ObjectPermission.READ,
    });
  }
}

function parseObjectPath(path: string): {
  bucketName: string;
  objectName: string;
} {
  if (!path.startsWith("/")) {
    path = `/${path}`;
  }
  const pathParts = path.split("/");
  if (pathParts.length < 3) {
    throw new Error("Invalid path: must contain at least a bucket name");
  }

  const bucketName = pathParts[1];
  const objectName = pathParts.slice(2).join("/");

  return {
    bucketName,
    objectName,
  };
}

async function signObjectURL({
  bucketName,
  objectName,
  method,
  ttlSec,
}: {
  bucketName: string;
  objectName: string;
  method: "GET" | "PUT" | "DELETE" | "HEAD";
  ttlSec: number;
}): Promise<string> {
  const request = {
    bucket_name: bucketName,
    object_name: objectName,
    method,
    expires_at: new Date(Date.now() + ttlSec * 1000).toISOString(),
  };
  const response = await fetch(
    `${REPLIT_SIDECAR_ENDPOINT}/object-storage/signed-object-url`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(request),
    }
  );
  if (!response.ok) {
    throw new Error(
      `Failed to sign object URL, errorcode: ${response.status}, ` +
        `make sure you're running on Replit`
    );
  }

  const { signed_url: signedURL } = await response.json();
  return signedURL;
}

client/src/pages/import-export.tsx.content:
/**
 * Module Import/Export de données KLYXOR
 * Permet l'import de données historiques depuis Excel/CSV
 * et l'export des données en différents formats
 * 
 * Fonctionnalités :
 * - Import Excel/CSV avec validation et gestion des doublons
 * - Export multi-format (Excel, CSV, PDF)
 * - Historique des imports avec rapport d'erreurs
 * - Téléchargement de modèles pré-formatés
 */
import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { useMutation, useQuery } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { 
  Upload, Download, FileSpreadsheet, CheckCircle2, XCircle, 
  AlertCircle, FileText, History, TrendingUp, Database,
  FileX, RefreshCw, Settings, ChevronRight
} from "lucide-react";

/**
 * Composant principal de gestion des imports/exports
 * Structure en 3 onglets : Import | Export | Historique
 */
export default function ImportExport() {
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useState("import");
  const [uploadFile, setUploadFile] = useState<File | null>(null);
  const [importOptions, setImportOptions] = useState({
    updateExisting: false,
    skipDuplicates: true,
    validateData: true,
    dataType: "contracts"
  });
  const [exportOptions, setExportOptions] = useState({
    format: "xlsx",
    includeArchived: false,
    dateRange: "all",
    dataTypes: [] as string[]
  });
  const [importProgress, setImportProgress] = useState(0);
  const [importStatus, setImportStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const [importResults, setImportResults] = useState<any>(null);

  // Récupération de l'historique des imports
  const { data: importHistory = [] } = useQuery({
    queryKey: ["/api/import-logs"],
  });

  // Récupération des jobs d'export
  const { data: exportJobs = [] } = useQuery({
    queryKey: ["/api/export-jobs"],
  });

  // Mutation pour l'import de fichier
  const importMutation = useMutation({
    mutationFn: async (formData: FormData) => {
      // Simulation de l'import avec progression
      setImportStatus('processing');
      setImportProgress(0);

      // Simulation de progression
      const progressInterval = setInterval(() => {
        setImportProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval);
            return 90;
          }
          return prev + 10;
        });
      }, 500);

      const response = await apiRequest("POST", "/api/import/excel", formData);
      clearInterval(progressInterval);
      setImportProgress(100);
      return response.json();
    },
    onSuccess: (data) => {
      setImportStatus('success');
      setImportResults(data);
      toast({
        title: "Import réussi",
        description: `${data.imported || 0} lignes importées avec succès`,
      });
      queryClient.invalidateQueries({ queryKey: ["/api/contracts"] });
      queryClient.invalidateQueries({ queryKey: ["/api/import-logs"] });
    },
    onError: (error) => {
      setImportStatus('error');
      toast({
        title: "Erreur d'import",
        description: "Une erreur est survenue lors de l'import",
        variant: "destructive",
      });
    },
  });

  // Mutation pour l'export
  const exportMutation = useMutation({
    mutationFn: async (options: any) => {
      return await apiRequest("POST", "/api/export", options);
    },
    onSuccess: async (response) => {
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `export_klyxor_${new Date().toISOString().split('T')[0]}.${exportOptions.format}`;
      a.click();
      window.URL.revokeObjectURL(url);

      toast({
        title: "Export réussi",
        description: "Le fichier a été téléchargé avec succès",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/export-jobs"] });
    },
    onError: (error) => {
      toast({
        title: "Erreur d'export",
        description: "Une erreur est survenue lors de l'export",
        variant: "destructive",
      });
    },
  });

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const validTypes = ['application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'text/csv'];
      if (!validTypes.includes(file.type)) {
        toast({
          title: "Format invalide",
          description: "Veuillez sélectionner un fichier Excel (.xlsx, .xls) ou CSV",
          variant: "destructive",
        });
        return;
      }
      setUploadFile(file);
      setImportStatus('idle');
      setImportResults(null);
    }
  };

  const handleImport = () => {
    if (!uploadFile) return;

    const formData = new FormData();
    formData.append('file', uploadFile);
    formData.append('options', JSON.stringify(importOptions));

    importMutation.mutate(formData);
  };

  const handleExport = () => {
    if (exportOptions.dataTypes.length === 0) {
      toast({
        title: "Sélection requise",
        description: "Veuillez sélectionner au moins un type de données à exporter",
        variant: "destructive",
      });
      return;
    }
    exportMutation.mutate(exportOptions);
  };

  return (
    <div className="flex flex-col h-full bg-gray-50">
      <main className="flex-1 overflow-y-auto p-4 lg:p-6">
        <div className="max-w-7xl mx-auto">
          {/* En-tête */}
          <div className="mb-6">
            <h1 className="text-3xl font-bold text-gray-900">Import / Export</h1>
            <p className="text-gray-500 mt-2">Gérez vos imports et exports de données</p>
          </div>

          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <TabsList className="grid w-full max-w-[600px] grid-cols-3">
              <TabsTrigger value="import">Import</TabsTrigger>
              <TabsTrigger value="export">Export</TabsTrigger>
              <TabsTrigger value="history">Historique</TabsTrigger>
            </TabsList>

            {/* Tab Import */}
            <TabsContent value="import" className="space-y-6">
              <div className="grid gap-6 lg:grid-cols-2">
                {/* Zone d'upload */}
                <Card>
                  <CardHeader>
                    <CardTitle>Import de données</CardTitle>
                    <CardDescription>
                      Importez vos données depuis un fichier Excel ou CSV
                    </CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="space-y-2">
                      <Label>Type de données</Label>
                      <Select 
                        value={importOptions.dataType}
                        onValueChange={(value) => setImportOptions({...importOptions, dataType: value})}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="contracts">Contrats</SelectItem>
                          <SelectItem value="amendments">Avenants</SelectItem>
                          <SelectItem value="indexations">Indexations</SelectItem>
                          <SelectItem value="deadlines">Échéances</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center">
                      <input
                        type="file"
                        id="import-file"
                        className="hidden"
                        accept=".xlsx,.xls,.csv"
                        onChange={handleFileSelect}
                      />
                      <label htmlFor="import-file" className="cursor-pointer">
                        {uploadFile ? (
                          <div className="space-y-2">
                            <FileSpreadsheet className="w-12 h-12 mx-auto text-green-500" />
                            <p className="text-sm font-medium">{uploadFile.name}</p>
                            <p className="text-xs text-gray-500">
                              {(uploadFile.size / 1024 / 1024).toFixed(2)} MB
                            </p>
                          </div>
                        ) : (
                          <>
                            <Upload className="w-12 h-12 mx-auto text-gray-400 mb-3" />
                            <p className="text-sm text-gray-600">
                              Glissez-déposez votre fichier ici ou{" "}
                              <span className="text-primary font-medium">parcourir</span>
                            </p>
                            <p className="text-xs text-gray-500 mt-2">
                              Excel (.xlsx, .xls) ou CSV
                            </p>
                          </>
                        )}
                      </label>
                    </div>

                    <div className="space-y-3">
                      <div className="flex items-center space-x-2">
                        <Checkbox 
                          id="update-existing"
                          checked={importOptions.updateExisting}
                          onCheckedChange={(checked) => 
                            setImportOptions({...importOptions, updateExisting: checked as boolean})
                          }
                        />
                        <Label htmlFor="update-existing">
                          Mettre à jour les enregistrements existants
                        </Label>
                      </div>
                      <div className="flex items-center space-x-2">
                        <Checkbox 
                          id="skip-duplicates"
                          checked={importOptions.skipDuplicates}
                          onCheckedChange={(checked) => 
                            setImportOptions({...importOptions, skipDuplicates: checked as boolean})
                          }
                        />
                        <Label htmlFor="skip-duplicates">
                          Ignorer les doublons
                        </Label>
                      </div>
                      <div className="flex items-center space-x-2">
                        <Checkbox 
                          id="validate-data"
                          checked={importOptions.validateData}
                          onCheckedChange={(checked) => 
                            setImportOptions({...importOptions, validateData: checked as boolean})
                          }
                        />
                        <Label htmlFor="validate-data">
                          Valider les données avant import
                        </Label>
                      </div>
                    </div>

                    <Button 
                      onClick={handleImport}
                      disabled={!uploadFile || importStatus === 'processing'}
                      className="w-full"
                    >
                      {importStatus === 'processing' ? (
                        <>
                          <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                          Import en cours...
                        </>
                      ) : (
                        <>
                          <Upload className="w-4 h-4 mr-2" />
                          Lancer l'import
                        </>
                      )}
                    </Button>
                  </CardContent>
                </Card>

                {/* Statut et résultats */}
                <div className="space-y-6">
                  {/* Progress */}
                  {importStatus === 'processing' && (
                    <Card>
                      <CardHeader>
                        <CardTitle>Import en cours</CardTitle>
                      </CardHeader>
                      <CardContent>
                        <Progress value={importProgress} className="mb-2" />
                        <p className="text-sm text-gray-500">{importProgress}% complété</p>
                      </CardContent>
                    </Card>
                  )}

                  {/* Résultats */}
                  {importResults && (
                    <Card>
                      <CardHeader>
                        <CardTitle>Résultats de l'import</CardTitle>
                      </CardHeader>
                      <CardContent className="space-y-3">
                        <div className="flex items-center justify-between">
                          <span className="text-sm">Lignes traitées</span>
                          <Badge variant="outline">{importResults.processed || 0}</Badge>
                        </div>
                        <div className="flex items-center justify-between">
                          <span className="text-sm">Importées avec succès</span>
                          <Badge variant="default">{importResults.imported || 0}</Badge>
                        </div>
                        <div className="flex items-center justify-between">
                          <span className="text-sm">Mises à jour</span>
                          <Badge variant="secondary">{importResults.updated || 0}</Badge>
                        </div>
                        <div className="flex items-center justify-between">
                          <span className="text-sm">Ignorées (doublons)</span>
                          <Badge variant="outline">{importResults.skipped || 0}</Badge>
                        </div>
                        <div className="flex items-center justify-between">
                          <span className="text-sm">Erreurs</span>
                          <Badge variant="destructive">{importResults.errors || 0}</Badge>
                        </div>
                      </CardContent>
                    </Card>
                  )}

                  {/* Template */}
                  <Card>
                    <CardHeader>
                      <CardTitle>Modèles de fichier</CardTitle>
                      <CardDescription>
                        Téléchargez les modèles Excel pour préparer vos données
                      </CardDescription>
                    </CardHeader>
                    <CardContent className="space-y-2">
                      <Button variant="outline" className="w-full justify-start">
                        <FileSpreadsheet className="w-4 h-4 mr-2" />
                        Modèle Contrats
                        <Download className="w-4 h-4 ml-auto" />
                      </Button>
                      <Button variant="outline" className="w-full justify-start">
                        <FileSpreadsheet className="w-4 h-4 mr-2" />
                        Modèle Avenants
                        <Download className="w-4 h-4 ml-auto" />
                      </Button>
                      <Button variant="outline" className="w-full justify-start">
                        <FileSpreadsheet className="w-4 h-4 mr-2" />
                        Modèle Indexations
                        <Download className="w-4 h-4 ml-auto" />
                      </Button>
                    </CardContent>
                  </Card>
                </div>
              </div>
            </TabsContent>

            {/* Tab Export */}
            <TabsContent value="export" className="space-y-6">
              <div className="grid gap-6 lg:grid-cols-2">
                <Card>
                  <CardHeader>
                    <CardTitle>Configuration de l'export</CardTitle>
                    <CardDescription>
                      Sélectionnez les données à exporter et le format souhaité
                    </CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <div className="space-y-2">
                      <Label>Format d'export</Label>
                      <RadioGroup 
                        value={exportOptions.format}
                        onValueChange={(value) => setExportOptions({...exportOptions, format: value})}
                      >
                        <div className="flex items-center space-x-2">
                          <RadioGroupItem value="xlsx" id="xlsx" />
                          <Label htmlFor="xlsx">Excel (.xlsx)</Label>
                        </div>
                        <div className="flex items-center space-x-2">
                          <RadioGroupItem value="csv" id="csv" />
                          <Label htmlFor="csv">CSV (.csv)</Label>
                        </div>
                        <div className="flex items-center space-x-2">
                          <RadioGroupItem value="pdf" id="pdf" />
                          <Label htmlFor="pdf">PDF</Label>
                        </div>
                      </RadioGroup>
                    </div>

                    <div className="space-y-2">
                      <Label>Types de données</Label>
                      <div className="space-y-2">
                        {['Contrats', 'Avenants', 'Indexations', 'Échéances', 'Documents'].map((type) => (
                          <div key={type} className="flex items-center space-x-2">
                            <Checkbox 
                              id={`export-${type}`}
                              checked={exportOptions.dataTypes.includes(type)}
                              onCheckedChange={(checked) => {
                                if (checked) {
                                  setExportOptions({
                                    ...exportOptions,
                                    dataTypes: [...exportOptions.dataTypes, type]
                                  });
                                } else {
                                  setExportOptions({
                                    ...exportOptions,
                                    dataTypes: exportOptions.dataTypes.filter(t => t !== type)
                                  });
                                }
                              }}
                            />
                            <Label htmlFor={`export-${type}`}>{type}</Label>
                          </div>
                        ))}
                      </div>
                    </div>

                    <div className="space-y-2">
                      <Label>Période</Label>
                      <Select 
                        value={exportOptions.dateRange}
                        onValueChange={(value) => setExportOptions({...exportOptions, dateRange: value})}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="all">Toutes les données</SelectItem>
                          <SelectItem value="current_year">Année en cours</SelectItem>
                          <SelectItem value="last_year">Année précédente</SelectItem>
                          <SelectItem value="last_quarter">Dernier trimestre</SelectItem>
                          <SelectItem value="custom">Personnalisée</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="flex items-center space-x-2">
                      <Checkbox 
                        id="include-archived"
                        checked={exportOptions.includeArchived}
                        onCheckedChange={(checked) => 
                          setExportOptions({...exportOptions, includeArchived: checked as boolean})
                        }
                      />
                      <Label htmlFor="include-archived">
                        Inclure les données archivées
                      </Label>
                    </div>

                    <Button 
                      onClick={handleExport}
                      disabled={exportMutation.isPending}
                      className="w-full"
                    >
                      {exportMutation.isPending ? (
                        <>
                          <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
                          Export en cours...
                        </>
                      ) : (
                        <>
                          <Download className="w-4 h-4 mr-2" />
                          Exporter les données
                        </>
                      )}
                    </Button>
                  </CardContent>
                </Card>

                {/* Exports récents */}
                <Card>
                  <CardHeader>
                    <CardTitle>Exports récents</CardTitle>
                    <CardDescription>
                      Historique des derniers exports effectués
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <div className="space-y-3">
                      {exportJobs.slice(0, 5).map((job: any, index: number) => (
                        <div key={index} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                          <div className="flex items-center space-x-3">
                            <FileSpreadsheet className="w-5 h-5 text-gray-400" />
                            <div>
                              <p className="text-sm font-medium">{job.fileName || `Export ${job.format}`}</p>
                              <p className="text-xs text-gray-500">
                                {new Date(job.createdAt).toLocaleDateString('fr-FR')}
                              </p>
                            </div>
                          </div>
                          <Button variant="ghost" size="sm">
                            <Download className="w-4 h-4" />
                          </Button>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              </div>
            </TabsContent>

            {/* Tab Historique */}
            <TabsContent value="history" className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle>Historique des imports</CardTitle>
                  <CardDescription>
                    Consultez l'historique complet des imports de données
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3">
                    {importHistory.map((log: any, index: number) => (
                      <div key={index} className="flex items-center justify-between p-4 border rounded-lg">
                        <div className="flex items-center space-x-4">
                          {log.status === 'success' ? (
                            <CheckCircle2 className="w-5 h-5 text-green-500" />
                          ) : log.status === 'error' ? (
                            <XCircle className="w-5 h-5 text-red-500" />
                          ) : (
                            <AlertCircle className="w-5 h-5 text-yellow-500" />
                          )}
                          <div>
                            <p className="font-medium">{log.fileName}</p>
                            <p className="text-sm text-gray-500">
                              {log.importType} • {new Date(log.createdAt).toLocaleDateString('fr-FR')}
                            </p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="text-sm font-medium">{log.totalRows} lignes</p>
                          <p className="text-xs text-gray-500">
                            {log.successCount} réussies, {log.errorCount} erreurs
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </TabsContent>
          </Tabs>
        </div>
      </main>
    </div>
  );
}

