    it('devrait gérer l\'import SAP avec mapping personnalisé', async () => {
      console.log('\n🔄 Test: Import SAP avec mapping');

      const sapImport = {
        fileName: 'SAP_CONTRACTS_20250904.xml',
        author: 'system_sap',
