  describe('📁 [Module GED] Gestion électronique des documents', () => {

    it('devrait uploader un document contractuel', async () => {
      console.log('\n📎 Test: Upload document contractuel');

      const document = {
        contractId: testContract.id,
        fileName: 'Contrat_ENGIE_2025_signe.pdf',
        fileType: 'application/pdf',
        fileSize: 2458000, // 2.4MB
        category: 'contract_signed',
        version: 1,
        uploadedBy: managerUser.id,
        uploadedAt: new Date(),
        status: 'active',
        checksum: 'sha256:abcd1234...',
        metadata: JSON.stringify({
          pages: 42,
          signatories: 3,
          signatureDate: '2024-12-15'
        })
      };

      [testDocument] = await db.insert(documents).values(document).returning();

      expect(testDocument.fileName).toBe('Contrat_ENGIE_2025_signe.pdf');
      expect(testDocument.fileSize).toBe('2458000');
      console.log(`✅ Document uploadé: ${testDocument.fileName} (${(2458000/1024/1024).toFixed(2)}MB)`);
    });

    it('devrait gérer le versioning des documents', async () => {
      console.log('\n🔄 Test: Versioning documents');

      // Nouvelle version du document
      const newVersion = {
        contractId: testContract.id,
        fileName: 'Contrat_ENGIE_2025_signe_v2.pdf',
        fileType: 'application/pdf',
        fileSize: 2512000,
        category: 'contract_signed',
        version: 2,
        uploadedBy: managerUser.id,
        uploadedAt: new Date(),
        status: 'active',
        previousVersionId: testDocument.id,
