      };

      const [v2Document] = await db.insert(documents).values(newVersion).returning();

      // Archivage ancienne version
      await db.update(documents)
        .set({ status: 'archived' })
        .where(eq(documents.id, testDocument.id));

      expect(v2Document.version).toBe(2);
      expect(v2Document.previousVersionId).toBe(testDocument.id);
      console.log(`✅ Version 2 créée, version 1 archivée`);
    });

    it('devrait rechercher des documents par métadonnées', async () => {
      console.log('\n🔍 Test: Recherche documents par métadonnées');

      // Ajout de documents avec métadonnées
      const docsToAdd = [
        {
          contractId: testContract.id,
          fileName: 'Avenant_001_2025.pdf',
          fileType: 'application/pdf',
          fileSize: 524000,
          category: 'amendment',
          uploadedBy: managerUser.id,
          tags: JSON.stringify(['avenant', 'révision tarifaire', '2025'])
        },
        {
          contractId: testContract.id,
          fileName: 'Facture_202509.pdf',
          fileType: 'application/pdf',
          fileSize: 185000,
          category: 'invoice',
          uploadedBy: managerUser.id,
          tags: JSON.stringify(['facture', 'septembre', '2025'])
        },
        {
          contractId: testContract.id,
          fileName: 'Rapport_audit_2025.pdf',
          fileType: 'application/pdf',
          fileSize: 1256000,
