    it('devrait générer un rapport de documents par contrat', async () => {
      console.log('\n📊 Test: Rapport documents par contrat');

      const contractDocs = await db.select()
        .from(documents)
        .where(eq(documents.contractId, testContract.id));

      const stats = {
        total: contractDocs.length,
        categories: {} as Record<string, number>,
        totalSize: 0,
        avgSize: 0
      };

      contractDocs.forEach(doc => {
        stats.categories[doc.category] = (stats.categories[doc.category] || 0) + 1;
